CREATE OR REPLACE VIEW lr_serverless_aws_us_catalog.bricksurance_semantics.asset_metrics
COMMENT 'Asset-side KPIs over the latest positions - market value, book value and the rating mix by portfolio and instrument type. Portfolio duration and stress are governed functions (fn_duration, fn_stress_mv), not measures. Amounts are in original currency; group by or filter on currency_code before summing money. Query measures with MEASURE(name).'
WITH METRICS
LANGUAGE YAML
AS $$
version: 0.1

source: lr_serverless_aws_us_catalog.bricksurance_investment.position

joins:
  - name: instrument
    source: lr_serverless_aws_us_catalog.bricksurance_investment.instrument
    on: source.instrument_id = instrument.instrument_id

dimensions:
  - name: portfolio_code
    expr: source.portfolio_code
  - name: instrument_type_code
    expr: instrument.instrument_type_code
  - name: credit_rating_code
    expr: instrument.credit_rating_code
  - name: as_of_month
    expr: source.as_of_month
  - name: currency_code
    expr: source.currency_code

measures:
  - name: asset_market_value
    expr: SUM(market_value)
  - name: asset_book_value
    expr: SUM(book_value)
  - name: position_count
    expr: COUNT(position_id)
$$;
